import { For, Show, createEffect, createMemo, createSignal, createUniqueId, onSettled, untrack } from 'solid-js';
import type { JSX } from '@solidjs/web';
import { animate, cubicBezier, inView } from 'motion';

type Easing = 'easeOut' | 'linear' | 'expo' | 'spring';

export interface CountUpProps {
  to: number;
  from?: number;
  direction?: 'up' | 'down';
  delay?: number;
  duration?: number;
  className?: string;
  style?: JSX.CSSProperties;
  startWhen?: boolean;
  separator?: string;
  prefix?: string;
  suffix?: string;
  mode?: 'count' | 'roll';
  easing?: Easing;
  decimals?: number;
  format?: 'standard' | 'compact';
  trigger?: 'view' | 'load';
  replayOnHover?: boolean;
  onStart?: () => void;
  onEnd?: () => void;
}

type Column = {
  slot: number;
  index: number;
  place: number;
  from: number;
  to: number;
  enter: boolean;
  leave: boolean;
  delta: number;
};

type Mark = { char: string; enter?: boolean; leave?: boolean; follow?: number };

type Slot = Column | Mark;

type Roll = { slots: Slot[]; columns: Column[]; label: string };

type Play = { id: number; from: number; to: number; spin: boolean; wait?: boolean };

const CELL = 1.2;
const STAGGER = 0.07;
const UNITS: [number, string][] = [
  [1e12, 'T'],
  [1e9, 'B'],
  [1e6, 'M'],
  [1e3, 'K']
];
const SLOT_STYLE: JSX.CSSProperties = { display: 'inline-block', height: `${CELL}em`, 'line-height': `${CELL}em` };
const SR_ONLY: JSX.CSSProperties = {
  position: 'absolute',
  width: '1px',
  height: '1px',
  padding: 0,
  margin: '-1px',
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  'white-space': 'nowrap',
  border: 0
};

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const smooth = (edge0: number, edge1: number, value: number) => {
  const t = clamp01((value - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};
const mod10 = (value: number) => ((value % 10) + 10) % 10;

const makeSpring = (overshoot: number) => {
  const log = Math.log(Math.min(0.5, Math.max(0.001, overshoot)));
  const zeta = -log / Math.sqrt(Math.PI * Math.PI + log * log);
  const damped = Math.PI / 0.52;
  const natural = damped / Math.sqrt(1 - zeta * zeta);
  const raw = (t: number) =>
    1 - Math.exp(-zeta * natural * t) * (Math.cos(damped * t) + ((zeta * natural) / damped) * Math.sin(damped * t));
  const residual = 1 - raw(1);
  return (t: number) => (t >= 1 ? 1 : raw(t) + residual * t * t * t);
};

const EASINGS: Record<Easing, (t: number) => number> = {
  linear: t => t,
  easeOut: cubicBezier(0.33, 1, 0.68, 1),
  expo: t => (t >= 1 ? 1 : (1 - Math.pow(2, -10 * t)) / (1 - Math.pow(2, -10))),
  spring: makeSpring(0.06)
};

const getDecimalPlaces = (num: number): number => {
  const str = num.toString();

  if (str.includes('.')) {
    const decimals = str.split('.')[1];

    if (parseInt(decimals) !== 0) {
      return decimals.length;
    }
  }

  return 0;
};

const unitFor = (value: number): [number, string] =>
  UNITS.find(([size]) => Math.abs(value) >= size * 0.9995) || [1, ''];

const scaleFor = (value: number, compact: boolean, decimals: number | undefined, places: number) => {
  if (!compact) return { size: 1, label: '', digits: places };
  const [size, label] = unitFor(value);
  const digits = decimals ?? (label ? (Math.abs(value) / size < 100 ? 1 : 0) : places);
  return { size, label, digits };
};

const splitNumber = (value: number, digits: number, size: number) => {
  const fixed = (Math.abs(value) / size).toFixed(digits);
  const [int, frac = ''] = fixed.split('.');
  return { negative: value < 0 && Number(fixed) !== 0, int, frac };
};

const group = (int: string, separator: string) => (separator ? int.replace(/\B(?=(\d{3})+(?!\d))/g, separator) : int);

type FormatOptions = {
  compact: boolean;
  decimals: number | undefined;
  places: number;
  separator: string;
  prefix: string;
  suffix: string;
};

const formatNumber = (latest: number, options: FormatOptions) => {
  const { size, label, digits } = scaleFor(latest, options.compact, options.decimals, options.places);
  const parts = splitNumber(latest, digits, size);
  const body = `${parts.negative ? '-' : ''}${group(parts.int, options.separator)}${parts.frac ? `.${parts.frac}` : ''}`;
  return `${options.prefix}${body}${label}${options.suffix}`;
};

const OFFSETS = [-1, 0, 1, 2];

const buildRoll = (
  a: number,
  b: number,
  spin: boolean,
  {
    compact,
    decimals,
    places,
    separator
  }: { compact: boolean; decimals: number | undefined; places: number; separator: string }
): Roll => {
  const { size, label, digits } = scaleFor(b, compact, decimals, places);
  const pa = splitNumber(a, digits, size);
  const pb = splitNumber(b, digits, size);
  const length = Math.max(pa.int.length, pb.int.length);
  const slots: Slot[] = [];
  const columns: Column[] = [];
  if (pa.negative || pb.negative) slots.push({ char: '-', enter: !pa.negative, leave: !pb.negative });
  const digitAt = (parts: { int: string; frac: string }, place: number) => {
    if (place < 0) return Number(parts.frac[-place - 1]);
    const index = parts.int.length - 1 - place;
    return index >= 0 ? Number(parts.int[index]) : null;
  };
  for (let place = length - 1; place >= -digits; place--) {
    if (place === -1) slots.push({ char: '.' });
    const start = digitAt(pa, place);
    const end = digitAt(pb, place);
    const column: Column = {
      slot: slots.length,
      index: columns.length,
      place,
      from: start ?? 0,
      to: end ?? 0,
      enter: start === null,
      leave: end === null,
      delta: 0
    };
    slots.push(column);
    columns.push(column);
    if (separator && place > 0 && place % 3 === 0) slots.push({ char: separator, follow: column.index });
  }
  const up = spin || b >= a;
  columns.forEach((column, index) => {
    const rank = columns.length - 1 - index;
    const base = up ? mod10(column.to - column.from) : -mod10(column.from - column.to);
    const turns = spin
      ? Math.max(1, 3 - rank)
      : Math.min(Math.floor(Math.abs(b - a) / (size * 10 ** (column.place + 1))), Math.max(0, 3 - rank));
    column.delta = base + (up ? 10 : -10) * turns;
  });
  return { slots, columns, label };
};

export default function CountUp(props: CountUpProps) {
  let ref: HTMLSpanElement | undefined;
  let textEl: HTMLSpanElement | undefined;
  let slotRefs: (HTMLSpanElement | undefined)[] = [];
  let filterRefs: (SVGFEGaussianBlurElement | undefined)[] = [];
  let value = 0;
  let started = false;
  let running = false;
  const uid = createUniqueId().replace(/[^\w-]/g, '');
  const [play, setPlay] = createSignal<Play | null>(null);
  const [isInView, setIsInView] = createSignal(false);

  const from = () => props.from ?? 0;
  const startValue = createMemo(() => ((props.direction ?? 'up') === 'down' ? props.to : from()));
  const endValue = createMemo(() => ((props.direction ?? 'up') === 'down' ? from() : props.to));
  const mode = () => props.mode ?? 'count';
  const compact = () => (props.format ?? 'standard') === 'compact';
  const places = createMemo(() => props.decimals ?? Math.max(getDecimalPlaces(from()), getDecimalPlaces(props.to)));
  const active = createMemo(() => (props.trigger ?? 'view') === 'load' || isInView());

  const formatOptions = createMemo<FormatOptions>(() => ({
    compact: compact(),
    decimals: props.decimals,
    places: places(),
    separator: props.separator ?? '',
    prefix: props.prefix ?? '',
    suffix: props.suffix ?? ''
  }));

  const model = createMemo<Roll | null>(() => {
    if (mode() !== 'roll') return null;
    const current = play();
    const a = current ? current.from : startValue();
    const b = current ? current.to : endValue();
    return buildRoll(a, b, !!current?.spin, {
      compact: compact(),
      decimals: props.decimals,
      places: places(),
      separator: props.separator ?? ''
    });
  });

  const live = () =>
    untrack(() => ({
      format: formatOptions(),
      onStart: props.onStart,
      onEnd: props.onEnd,
      model: model(),
      mode: mode(),
      easing: props.easing ?? 'easeOut',
      duration: Math.max(0, props.duration ?? 2),
      delay: props.delay ?? 0
    }));

  createEffect(
    () => ({ mode: mode(), start: startValue(), format: formatOptions() }),
    next => {
      if (!started) value = next.start;
      if (next.mode === 'count' && !running && textEl) textEl.textContent = formatNumber(value, next.format);
    }
  );

  createEffect(
    () => ({ go: active() && (props.startWhen ?? true), to: endValue() }),
    next => {
      if (!next.go) return undefined;
      started = true;
      let cancelled = false;
      queueMicrotask(() => {
        if (cancelled) return;
        setPlay(previous => ({
          id: (previous?.id || 0) + 1,
          from: value,
          to: next.to,
          spin: false,
          wait: true
        }));
      });
      return () => {
        cancelled = true;
      };
    }
  );

  createEffect(play, current => {
    const state = live();
    if (!current) return undefined;
    const ease = EASINGS[state.easing] || EASINGS.easeOut;
    const total = state.duration;
    const progress = (t: number) => (total > 0 ? clamp01(t / total) : 1);
    let render: (t: number) => void;

    if (state.mode === 'roll' && state.model && ref) {
      const { columns: layout, slots } = state.model;
      const fontSize = parseFloat(getComputedStyle(ref).fontSize) || 16;
      const cell = CELL * fontSize;
      const stagger = layout.length > 1 ? Math.min(STAGGER, (total * 0.4) / (layout.length - 1)) : 0;
      const span = Math.max(0.001, total - stagger * (layout.length - 1));
      const columns = layout.map(column => {
        const box = slotRefs[column.slot];
        const strip = box?.firstChild as HTMLSpanElement | null;
        return {
          ...column,
          box,
          strip,
          blur: filterRefs[column.index],
          cells: strip ? Array.from(strip.childNodes, node => node.firstChild) : ([] as (ChildNode | null)[]),
          width: box ? box.scrollWidth : 0,
          ease:
            state.easing === 'spring'
              ? makeSpring(Math.min(0.12, Math.max(0.01, 0.35 / Math.max(1, Math.abs(column.delta)))))
              : ease,
          base: Math.floor(column.from),
          sigma: 0,
          presence: column.enter ? 0 : 1
        };
      });
      const marks = slots
        .map((slot, index) => ({ ...slot, node: slotRefs[index] }))
        .filter(
          (slot): slot is Mark & { node: HTMLSpanElement } =>
            'char' in slot && !!slot.node && (!!slot.enter || !!slot.leave || slot.follow !== undefined)
        )
        .map(slot => ({ ...slot, width: slot.node.scrollWidth }));

      const fade = (node: HTMLSpanElement | null | undefined, width: number, presence: number, settled: boolean) => {
        if (!node) return;
        node.style.width = settled ? '' : `${(presence * width).toFixed(2)}px`;
        node.style.opacity = settled ? '' : presence.toFixed(3);
      };

      render = (t: number) => {
        columns.forEach((column, index) => {
          if (!column.strip) return;
          const u = clamp01((t - index * stagger) / span);
          const pos = column.from + column.delta * column.ease(u);
          const base = Math.floor(pos);
          if (base !== column.base) {
            column.base = base;
            column.cells.forEach((node, offset) => {
              if (node) node.nodeValue = String(mod10(base + offset - 1));
            });
          }
          column.strip.style.transform = `translateY(${(-(1 + pos - base) * CELL).toFixed(4)}em)`;

          const u0 = Math.max(0, u - 0.004);
          const u1 = Math.min(1, u + 0.004);
          const speed =
            u1 > u0 ? (Math.abs(column.delta) * Math.abs(column.ease(u1) - column.ease(u0))) / (u1 - u0) / span : 0;
          const sigma = u > 0 && u < 1 ? Math.min(cell * 0.05, (speed * cell) / 600) : 0;
          if (Math.abs(sigma - column.sigma) > 0.05 || (sigma === 0 && column.sigma !== 0)) {
            column.sigma = sigma;
            if (sigma > 0.2 && column.blur) {
              column.blur.setAttribute('stdDeviation', `0 ${sigma.toFixed(2)}`);
              column.strip.style.filter = `url(#${uid}-${index})`;
            } else {
              column.strip.style.filter = '';
            }
          }

          if (column.enter || column.leave) {
            column.presence = column.enter ? smooth(0, 0.45, u) : 1 - smooth(0.55, 1, u);
            fade(column.box, column.width, column.presence, column.enter && u >= 1);
          }
        });

        const overall = progress(t);
        marks.forEach(mark => {
          if (mark.follow !== undefined) {
            const column = columns[mark.follow];
            if (column && (column.enter || column.leave))
              fade(mark.node, mark.width, column.presence, column.enter && column.presence >= 1);
          } else {
            const presence = mark.enter ? smooth(0, 0.3, overall) : 1 - smooth(0.7, 1, overall);
            fade(mark.node, mark.width, presence, !!mark.enter && overall >= 1);
          }
        });

        value = current.from + (current.to - current.from) * ease(overall);
      };
    } else {
      render = (t: number) => {
        const next = current.from + (current.to - current.from) * ease(progress(t));
        value = next;
        if (textEl) textEl.textContent = formatNumber(next, live().format);
      };
    }

    running = true;
    if (typeof state.onStart === 'function') state.onStart();

    const finish = () => {
      render(Infinity);
      value = current.to;
      running = false;
      live().onEnd?.();
    };

    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      finish();
      return undefined;
    }

    const controls = animate(0, total, {
      duration: total,
      delay: current.wait ? state.delay : 0,
      ease: 'linear',
      onUpdate: render,
      onComplete: finish
    });

    return () => {
      controls.stop();
      running = false;
    };
  });

  onSettled(() => {
    const el = ref;
    if (!el) return;
    const stop = inView(
      el,
      () => {
        setIsInView(true);
        stop();
      },
      { margin: '0px' }
    );
    return () => {
      stop();
    };
  });

  const replay = () => {
    if (!props.replayOnHover || running || !started) return;
    const roll = mode() === 'roll';
    const a = startValue();
    const b = endValue();
    setPlay(previous =>
      roll
        ? { id: (previous?.id || 0) + 1, from: value, to: value, spin: true }
        : { id: (previous?.id || 0) + 1, from: a, to: b, spin: false }
    );
  };

  const finalText = () => formatNumber(play()?.to ?? endValue(), formatOptions());

  return (
    <span
      class={props.className}
      ref={el => (ref = el)}
      style={{ 'font-variant-numeric': 'tabular-nums', ...props.style }}
      onPointerEnter={() => replay()}
    >
      <Show when={model()} keyed fallback={<span ref={el => (textEl = el)} />}>
        {roll => {
          slotRefs = [];
          filterRefs = [];
          return (
            <>
              <span aria-hidden="true" style={{ display: 'inline-flex', 'white-space': 'pre', 'user-select': 'none' }}>
                {props.prefix && <span style={SLOT_STYLE}>{props.prefix}</span>}
                <For each={roll.slots.map((slot, index) => ({ slot, index }))}>
                  {({ slot, index }) => {
                    const hidden =
                      'char' in slot
                        ? slot.enter || (slot.follow !== undefined && roll.columns[slot.follow].enter)
                        : slot.enter;
                    const collapsed: JSX.CSSProperties = hidden ? { width: 0, opacity: 0 } : {};
                    if ('char' in slot) {
                      return (
                        <span
                          ref={node => {
                            slotRefs[index] = node;
                          }}
                          style={{ ...SLOT_STYLE, overflow: 'hidden', ...collapsed }}
                        >
                          {slot.char}
                        </span>
                      );
                    }
                    return (
                      <span
                        ref={node => {
                          slotRefs[index] = node;
                        }}
                        style={{ ...SLOT_STYLE, position: 'relative', overflow: 'hidden', ...collapsed }}
                      >
                        <span
                          style={{ display: 'flex', 'flex-direction': 'column', transform: `translateY(${-CELL}em)` }}
                        >
                          <For each={OFFSETS}>
                            {offset => <span style={{ height: `${CELL}em` }}>{mod10(slot.from + offset)}</span>}
                          </For>
                        </span>
                      </span>
                    );
                  }}
                </For>
                {roll.label && <span style={SLOT_STYLE}>{roll.label}</span>}
                {props.suffix && <span style={SLOT_STYLE}>{props.suffix}</span>}
              </span>
              <span style={SR_ONLY}>{finalText()}</span>
              <svg aria-hidden="true" width="0" height="0" style={{ position: 'absolute' }}>
                <defs>
                  <For each={roll.columns}>
                    {column => (
                      <filter
                        id={`${uid}-${column.index}`}
                        x="-20%"
                        y="-50%"
                        width="140%"
                        height="200%"
                        color-interpolation-filters="sRGB"
                      >
                        <feGaussianBlur
                          ref={node => {
                            filterRefs[column.index] = node;
                          }}
                          stdDeviation="0 0"
                        />
                      </filter>
                    )}
                  </For>
                </defs>
              </svg>
            </>
          );
        }}
      </Show>
    </span>
  );
}
